import {testIdProps} from '@github-ui/test-id-props'
import {Banner, Button} from '@primer/react'
import {useState} from 'react'
import {usePromptCompareManager} from '../prompt-compare-manager'
import {closeSampleBannerPayload, useUpdateRepoModelsSettings} from '../../../hooks/use-update-repository-settings'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import type {PromptAppPayload} from '../types'

export function ShowSampleBanner() {
  const {
    payload: {repository},
  } = useAppPayload<PromptAppPayload>()
  const manager = usePromptCompareManager()
  const [showBanner, setShowBanner] = useState(true)
  const updateSettings = useUpdateRepoModelsSettings(repository.ownerLogin, repository.name)

  if (!showBanner) {
    return null
  }

  return (
    <Banner
      {...testIdProps('run-sample-banner')}
      title="Sample data info"
      hideTitle
      description={
        <>
          Compare and run prompts against multiple models. We prefilled the table with an example, but you can{' '}
          <Button
            variant="link"
            onClick={() => {
              manager.evalsClear()
            }}
          >
            clear the session
          </Button>{' '}
          and start from scratch anytime.
        </>
      }
      variant="info"
      className="mb-2"
      primaryAction={
        <Button
          {...testIdProps('run-sample-banner-save-button')}
          variant="default"
          disabled={updateSettings.isPending}
          onClick={async () => {
            await updateSettings.mutateAsync(closeSampleBannerPayload())
            setShowBanner(false)
          }}
        >
          Don&apos;t pre-fill the table again
        </Button>
      }
      onDismiss={() => setShowBanner(false)}
    />
  )
}
