import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {CollapsibleNavList} from '@github-ui/layout-primitives/CollapsibleNavList'
import {CollapsibleSidebar, useCollapsibleSidebarContext} from '@github-ui/layout-primitives/CollapsibleSidebar'
import {SidebarPageLayout} from '@github-ui/layout-primitives/SidebarPageLayout'
import {modelsCatalogPath, repoModelsPath} from '@github-ui/paths'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {Link, useLocation, useMatch, useResolvedPath} from '@github-ui/react-router'
import {
  AppsIcon,
  ArrowUpRightIcon,
  BookIcon,
  CommandPaletteIcon,
  CommentIcon,
  HomeIcon,
  NoteIcon,
  SidebarExpandIcon,
} from '@primer/octicons-react'
import {Heading, IconButton, Label, NavList, PageLayout, type PageLayoutContentProps, Tooltip} from '@primer/react'
import {clsx} from 'clsx'
import type {PropsWithChildren} from 'react'
import {aboutGitHubModelsDocsUrl} from '../constants'
import type {ModelRepoPayload} from '../types'
import styles from './ModelsRepoLayout.module.css'

const SIDEBAR_STORAGE_KEY = 'models-repo-sidebar'
const SIDEBAR_ARIA_LABEL = 'Models sidebar navigation'

function NavItem({
  to,
  children,
  icon,
  trailingIcon,
}: {
  to: string
  children: React.ReactNode
  icon: React.ReactNode
  trailingIcon?: React.ReactNode
}) {
  const resolved = useResolvedPath(to)
  let isCurrent = !!useMatch({path: resolved.pathname, end: true})

  const currentPath = useLocation().pathname

  // Special case for playground route since `models/playground` redirects to `models/:publisher/:modelName/playground`
  if (to.endsWith('/playground')) {
    const playgroundPathRegex = /^\/[^/]+\/[^/]+\/models\/[^/]+\/[^/]+\/playground$/ // Matches `/:owner/:repo/models/:publisher/:modelName/playground`
    isCurrent = playgroundPathRegex.test(currentPath)
  }

  return (
    <NavList.Item href={to} aria-current={isCurrent ? 'page' : undefined}>
      <NavList.LeadingVisual>{icon}</NavList.LeadingVisual>
      {children}
      {trailingIcon ? <NavList.TrailingVisual>{trailingIcon}</NavList.TrailingVisual> : null}
    </NavList.Item>
  )
}

type NavItemData = {
  id: string
  path: string
  icon: React.ComponentType<{size?: number; className?: string}>
  label: string
  isCurrent?: boolean
  forceHardNavigation?: boolean
}

type NavData = {
  repository: ModelRepoPayload['repository']
  canEdit: boolean
  isMarketplaceEnabled: boolean
  playgroundPath: string | null
  items: NavItemData[]
  catalogItem: NavItemData | null
}

function useNavItems(): NavData {
  const {repository, canEdit, isMarketplaceEnabled} = useAppPayload<ModelRepoPayload>()
  const marketplacePath = isMarketplaceEnabled ? '/marketplace/models' : null
  const playgroundPath = canEdit ? repoModelsPath({repo: repository, action: 'playground'}) : marketplacePath

  const overviewPath = repoModelsPath({repo: repository, action: ''})
  const promptsPath = repoModelsPath({repo: repository, action: 'prompts'})

  const overviewResolved = useResolvedPath(overviewPath)
  const promptsResolved = useResolvedPath(promptsPath)
  const playgroundResolved = useResolvedPath(playgroundPath ?? '')

  const isOverviewCurrent = !!useMatch({path: overviewResolved.pathname, end: true})
  const isPromptsCurrent = !!useMatch({path: promptsResolved.pathname, end: true})
  let isPlaygroundCurrent = !!useMatch({path: playgroundResolved.pathname, end: true})

  const currentPath = useLocation().pathname
  if (playgroundPath?.endsWith('/playground')) {
    const playgroundPathRegex = /^\/[^/]+\/[^/]+\/models\/[^/]+\/[^/]+\/playground$/
    isPlaygroundCurrent = playgroundPathRegex.test(currentPath)
  }

  const items: NavItemData[] = [
    {id: 'overview', path: overviewPath, icon: HomeIcon, label: 'Overview', isCurrent: isOverviewCurrent},
    {id: 'prompts', path: promptsPath, icon: NoteIcon, label: 'Prompts', isCurrent: isPromptsCurrent},
  ]

  if (playgroundPath) {
    items.push({
      id: 'playground',
      path: playgroundPath,
      icon: CommandPaletteIcon,
      label: 'Playground',
      isCurrent: isPlaygroundCurrent,
      forceHardNavigation: !canEdit && isMarketplaceEnabled,
    })
  }

  const catalogItem: NavItemData | null = isMarketplaceEnabled
    ? {id: 'catalog', path: modelsCatalogPath(), icon: AppsIcon, label: 'Catalog', forceHardNavigation: true}
    : null

  return {repository, canEdit, isMarketplaceEnabled, playgroundPath, items, catalogItem}
}

export function ModelsRepoLayout({
  children,
  fileTreeExpanded,
  setFileTreeExpanded,
  width = 'large' as const,
}: PropsWithChildren<{
  fileTreeExpanded: boolean
  setFileTreeExpanded: (expanded: boolean) => void
  width?: PageLayoutContentProps['width']
}>) {
  const useSidebarLayout = isFeatureEnabled('repo_models_sidebar_layout')

  if (useSidebarLayout) {
    return <ModelsRepoSidebarLayout width={width}>{children}</ModelsRepoSidebarLayout>
  }

  return (
    <ModelsRepoLegacyLayout fileTreeExpanded={fileTreeExpanded} setFileTreeExpanded={setFileTreeExpanded} width={width}>
      {children}
    </ModelsRepoLegacyLayout>
  )
}

// ---------------------------------------------------------------------------
// New sidebar layout (flag ON)

function ModelsRepoSidebarLayout({
  children,
  width = 'large' as const,
}: PropsWithChildren<{
  width?: PageLayoutContentProps['width']
}>) {
  const {repository} = useAppPayload<ModelRepoPayload>()
  const nav = useNavItems()

  return (
    <CurrentRepositoryProvider repository={repository}>
      <SidebarPageLayout storageKey={SIDEBAR_STORAGE_KEY}>
        <SidebarPageLayout.Sidebar
          aria-label={SIDEBAR_ARIA_LABEL}
          dialogTitle="Models"
          expandedWidth="small"
          footer={({isExpanded}) => (
            <>
              <ModelsFooterLinks isExpanded={isExpanded} />
              <CollapsibleSidebar.Toggle />
            </>
          )}
        >
          <ModelsSidebarContent nav={nav} />
        </SidebarPageLayout.Sidebar>
        <SidebarPageLayout.Content as="section" width={width === 'full' ? 'full' : 'xlarge'}>
          <div className="fill-page-height" data-hpc>
            {children}
          </div>
        </SidebarPageLayout.Content>
      </SidebarPageLayout>
    </CurrentRepositoryProvider>
  )
}

function ModelsSidebarContent({nav}: {nav: NavData}) {
  const {isExpanded} = useCollapsibleSidebarContext()

  return (
    <>
      {isExpanded && (
        <Heading as="h2" className="f3 tmp-pl-3 tmp-pt-3">
          <div className="d-flex flex-items-center">
            Models{' '}
            <Label variant="success" className="ml-2">
              Preview
            </Label>
          </div>
        </Heading>
      )}
      <CollapsibleNavList aria-label="Models navigation">
        {nav.items.map(item => (
          <CollapsibleNavList.LinkItem
            key={item.id}
            to={item.path}
            icon={item.icon}
            label={item.label}
            aria-current={item.isCurrent ? 'page' : undefined}
            forceHardNavigation={item.forceHardNavigation}
          />
        ))}
      </CollapsibleNavList>
      {nav.catalogItem && (
        <>
          <NavList.Divider />
          <CollapsibleNavList aria-label="External links">
            {isExpanded ? (
              <NavItem to={nav.catalogItem.path} icon={<nav.catalogItem.icon />} trailingIcon={<ArrowUpRightIcon />}>
                {nav.catalogItem.label}
              </NavItem>
            ) : (
              <CollapsibleNavList.LinkItem
                to={nav.catalogItem.path}
                icon={nav.catalogItem.icon}
                label={nav.catalogItem.label}
                forceHardNavigation
              />
            )}
          </CollapsibleNavList>
        </>
      )}
    </>
  )
}

const FEEDBACK_URL = 'https://github.com/orgs/community/discussions/categories/models'

function ModelsFooterLinks({isExpanded}: {isExpanded: boolean}) {
  return (
    <NavList aria-label="Feedback" className={styles.footerLinks}>
      <Tooltip text="Docs" direction="e" _privateDisableTooltip={isExpanded}>
        <NavList.Item href={aboutGitHubModelsDocsUrl} target="_blank" rel="noopener noreferrer">
          <NavList.LeadingVisual>
            <BookIcon />
          </NavList.LeadingVisual>
          Docs
        </NavList.Item>
      </Tooltip>
      <Tooltip text="Feedback" direction="e" _privateDisableTooltip={isExpanded}>
        <NavList.Item href={FEEDBACK_URL} target="_blank" rel="noopener noreferrer">
          <NavList.LeadingVisual>
            <CommentIcon />
          </NavList.LeadingVisual>
          Feedback
          {isExpanded && (
            <NavList.TrailingVisual>
              <Label variant="success">Preview</Label>
            </NavList.TrailingVisual>
          )}
        </NavList.Item>
      </Tooltip>
    </NavList>
  )
}

// ---------------------------------------------------------------------------
// Legacy layout (flag OFF)

function ModelsRepoLegacyLayout({
  children,
  fileTreeExpanded,
  setFileTreeExpanded,
  width = 'large' as const,
}: PropsWithChildren<{
  fileTreeExpanded: boolean
  setFileTreeExpanded: (expanded: boolean) => void
  width?: PageLayoutContentProps['width']
}>) {
  const {repository, canEdit, isMarketplaceEnabled} = useAppPayload<ModelRepoPayload>()
  const marketplacePath = isMarketplaceEnabled ? '/marketplace/models' : null
  const playgroundPath = canEdit ? repoModelsPath({repo: repository, action: 'playground'}) : marketplacePath

  return (
    <CurrentRepositoryProvider repository={repository}>
      <PageLayout containerWidth="full" columnGap="none" padding="none">
        {fileTreeExpanded && (
          <PageLayout.Pane
            padding="condensed"
            position="start"
            hidden={{
              narrow: true,
              regular: false,
              wide: false,
            }}
            divider="line"
            sticky
          >
            <div className="d-flex flex-column height-full tmp-pl-3 tmp-pt-3">
              <div className="d-flex flex-justify-between">
                <Heading as="h2" className="f3" id="pane-heading">
                  <div className="d-flex flex-items-center">
                    Models{' '}
                    <Label variant="success" className="ml-2">
                      Preview
                    </Label>
                  </div>
                </Heading>
                <IconButton
                  onClick={() => setFileTreeExpanded(false)}
                  aria-label="Collapse menu"
                  icon={SidebarExpandIcon}
                  variant="invisible"
                />
              </div>
              <NavList className="flex-1">
                <NavItem
                  to={repoModelsPath({
                    repo: repository,
                    action: '',
                  })}
                  icon={<HomeIcon />}
                >
                  Overview
                </NavItem>
                <NavItem
                  to={repoModelsPath({
                    repo: repository,
                    action: 'prompts',
                  })}
                  icon={<NoteIcon />}
                >
                  Prompts
                </NavItem>
                {playgroundPath && (
                  <NavItem
                    to={playgroundPath}
                    icon={<CommandPaletteIcon />}
                    trailingIcon={canEdit ? undefined : <ArrowUpRightIcon />}
                  >
                    Playground
                  </NavItem>
                )}
                <NavList.Divider />
                {isMarketplaceEnabled && (
                  <NavItem to={modelsCatalogPath()} icon={<AppsIcon />} trailingIcon={<ArrowUpRightIcon />}>
                    Catalog
                  </NavItem>
                )}
              </NavList>
              <div className="d-flex flex-justify-between my-2">
                <div>
                  <Link to={aboutGitHubModelsDocsUrl}>Docs</Link>
                  <span className="mx-1">·</span>
                  <Link to="https://github.com/orgs/community/discussions/categories/models">Share feedback</Link>
                </div>
              </div>
            </div>
          </PageLayout.Pane>
        )}
        <PageLayout.Content
          className={clsx(styles.content, 'fill-page-height')}
          padding="condensed"
          width={width}
          as="section"
        >
          <div className="fill-page-height" data-hpc>
            {children}
          </div>
        </PageLayout.Content>
      </PageLayout>
    </CurrentRepositoryProvider>
  )
}
